INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1896360', 'Battle of Skopje', 'The Battle of Skopje was a battle in 1004 during the Byzantine reconquest of Bulgaria. The campaign was carried out in a slow and systematic manner, with campaigns sometimes continuing year-round rather than following the traditional seasonal pattern.', 1004, NULL, NULL, NULL, NULL, NULL, 'year', '1004', 50, 'https://en.wikipedia.org/wiki/Battle_of_Skopje'),
  ('Q2888155', 'Battle of Bitola', 'The battle of Bitola (Bulgarian: Битка при Битоля) took place near the town of Bitola, in Bulgarian territory, between a Bulgarian army under the command of the voivode Ivats and a Byzantine army led by the strategos George Gonitsiates. It was one of the last open battles between the First Bulgarian Empire and the Byzantine Empire.', 1015, NULL, NULL, NULL, NULL, NULL, 'year', '1015', 45, 'https://en.wikipedia.org/wiki/Battle_of_Bitola_(1015)'),
  ('Q3302743', 'Battle of Otonetë', 'The Battle of Otonetë (Albanian: Beteja e Otonetës) occurred on September 27, 1446, in upper Dibra in Albania. The Ottoman commander, Mustafa Pasha, was sent into Albania, but was soon intercepted and defeated by Skanderbeg.', 1446, 9, 27, NULL, NULL, NULL, 'day', '27 September 1446', 41, 'https://en.wikipedia.org/wiki/Battle_of_Otonet%C3%AB'),
  ('Q3301210', 'Battle of Oranik', 'The First Battle of Oranik (Albanian: Beteja e Parë e Oranikut) took place during the Albanian-Venetian War of (1447–1448), when the Republic of Venice allied with the Ottoman Empire against the League of Lezhë. The Albanian forces under Skanderbeg defeated the Ottoman army led by Mustafa Pasha during a battle that took place near Oranik of Upper Dibra, and two months later, peace was established between Albania and Venice.', 1448, 8, 14, NULL, NULL, NULL, 'day', '14 August 1448', 37, 'https://en.wikipedia.org/wiki/Battle_of_Oranik_(1448)'),
  ('Q3302682', 'Siege of Svetigrad', 'The siege of Svetigrad or Sfetigrad (Albanian: Rrethimi i Sfetigradit) began on 14 May 1448 when an Ottoman army, led by Sultan Murad II, besieged the fortress of Svetigrad (now Kodžadžik, North Macedonia). After the many failed Ottoman expeditions into Albania against the League of Lezhë, a confederation of Albanian Principalities created in 1444 and headed by Skanderbeg, Murad II decided to march an army into Skanderbeg''s dominions in order to capture the key Albanian fortress of Svetigrad.', 1448, 5, 14, 1448, 7, 31, 'day', '14 May 1448 – 31 July 1448', 45, 'https://en.wikipedia.org/wiki/Siege_of_Svetigrad'),
  ('Q3298782', 'Battle of Oranik', 'The Second Battle of Oranik (Albanian: Beteja e Dytë e Oranikut) took place during the spring of 1456 in the plains of Oranik (Debar in modern-day Macedonia). Moisi Arianit Golemi, lord of Debar, and one of Skanderbeg''s officers, deserted to the Ottomans following the defeat at Berat in 1455.', 1456, 5, 18, NULL, NULL, NULL, 'day', '18 May 1456', 41, 'https://en.wikipedia.org/wiki/Battle_of_Oranik_(1456)'),
  ('Q3338499', 'Battle of Ohrid', 'The Battle of Ohrid (Albanian: Beteja e Ohrit) took place on 14 or 15 September 1464 between Albanian ruler Skanderbeg''s forces and Ottoman forces. A crusade against Sultan Mehmed II had been planned by Pope Pius II with Skanderbeg as one of its main leaders.', 1464, 9, 14, 1464, 9, 15, 'day', '14 September 1464 – 15 September 1464', 45, 'https://en.wikipedia.org/wiki/Battle_of_Ohrid'),
  ('Q4871725', 'Battle of Meçad', 'The Battle of Meçad (Albanian: Beteja e Meçadit) took place in July 1465 between Skanderbeg''s Albanian forces and Ballaban Badera''s Ottoman forces. Skanderbeg had been leading a war against the Ottoman Empire for over two decades and Ballaban Badera was an Ottoman captain of Albanian origin who had been recruited through the devşirme system.', 1465, NULL, NULL, NULL, NULL, NULL, 'year', '1465', 34, 'https://en.wikipedia.org/wiki/Battle_of_Me%C3%A7ad_(1465)'),
  ('Q4872638', 'Battle of Vaikal', 'The Battle of Vajkal or Battle of Valkal (Albanian: Beteja e Vajkalit) was fought in April of 1465 between the Albanian forces of Skanderbeg and an Ottoman army under Ballaban Pasha, an Ottoman commander of Albanian origin. Ballaban, the new Ottoman sanjakbey of the Sanjak of Ohrid, was sent by Sultan Mehmed II to attack the Albanian forces.', 1465, 4, 1, NULL, NULL, NULL, 'day', '1 April 1465', 37, 'https://en.wikipedia.org/wiki/Battle_of_Vajkal'),
  ('Q2346983', 'Battle of Kumanovo', 'The Battle of Kumanovo (Serbian: Кумановска битка/Kumanovska bitka, Turkish: Kumanova muharebesi), on 23–24 October 1912, was a major battle of the First Balkan War. It was an important Serbian victory over the Ottoman army in the Kosovo Vilayet, shortly after the outbreak of the war.', 1912, 10, 23, 1912, 10, 24, 'day', '23 October 1912 – 24 October 1912', 58, 'https://en.wikipedia.org/wiki/Battle_of_Kumanovo'),
  ('Q3392743', 'Battle of Monastir', 'The Battle of Monastir (Serbian: Битољска битка) took place near the town of Monastir (now Bitola) in the Macedonia region (the then capital of the Manastir vilayet) during the First Balkan War, between Serbian and Ottoman forces, from 16 to 19 November 1912. It resulted in a Serbian victory after heavy fighting north of the city, the routed Ottomans fled abandoning their guns.', 1912, 11, 16, 1912, 11, 19, 'day', '16 November 1912 – 19 November 1912', 55, 'https://en.wikipedia.org/wiki/Battle_of_Monastir'),
  ('Q3393985', 'Battle of Prilep', 'The Battle of Prilep in the First Balkan War took place on 3-5 November 1912 when the Serbian army encountered Ottoman troops near the town of Prilep, in today''s North Macedonia. The clash lasted for three days.', 1912, 11, 3, 1912, 11, 5, 'day', '3 November 1912 – 5 November 1912', 51, 'https://en.wikipedia.org/wiki/Battle_of_Prilep'),
  ('Q1534814', 'Ohrid–Debar Uprising', 'The Ohrid–Debar uprising (Macedonian: Охридско-Дебaрско вoстание, romanized: Ohridsko-Debarsko vostanie; Bulgarian: Охридско-Дебърско въстание, romanized: Ohridsko-Debarsko vastanie; Albanian: Kryengritja e Ohrit dhe Dibrës) was an uprising by the population in Western Macedonia, then Kingdom of Serbia, in September 1913. It was organized by the Internal Macedonian Revolutionary Organization (IMRO) and Albania against the Serbian capture of the regions of Ohrid, Debar and Struga after the Balkan Wars (1912–13).', 1913, 9, 23, NULL, NULL, NULL, 'day', '23 September 1913', 45, 'https://en.wikipedia.org/wiki/Ohrid%E2%80%93Debar_uprising'),
  ('Q2457686', 'Ovče Pole Offensive', 'The Ovche Pole Offensive Operation (Bulgarian: Овчеполска настъпателна операция, Serbian: Битка на Овчем Пољу) was an operation of the Bulgarian Army that occurred between 14 October 1915 and 15 November 1915 as part of the Serbian campaign of 1915 in World War I. It aimed to seize the Vardar river valley and to cut the vital railway linking Skopje with Thessaloniki to prevent the Serbian Army from being resupplied and reinforced by the Franco-British Allied forces. The Bulgarian forces consisted of the Second Army (3rd Balkan Infantry Division, 7th Rila Division and the Cavalry Division…', 1915, 11, 15, 1915, 11, 15, 'day', '15 November 1915', 45, 'https://en.wikipedia.org/wiki/Ov%C4%8De_Pole_Offensive'),
  ('Q4087436', 'Battle of Krivolak', 'The Battle of Krivolak (in Bulgarian: Криволашко сражение, Битка при Криволак) was a World War I battle, fought between 21 October and 22 November 1915. It was fought in the initial stage of the Macedonian campaign, in the Balkans Theatre.', 1915, 11, 22, 1915, 11, 21, 'day', '22 November 1915 – 21 November 1915', 48, 'https://en.wikipedia.org/wiki/Battle_of_Krivolak'),
  ('Q16253672', 'Battle of Kosturino', 'The Battle of Kosturino was a World War I battle fought between 6 and 12 December 1915. It was fought in the initial stage of the Macedonian campaign, in the Balkans Theatre.', 1915, 12, 6, 1915, 12, 12, 'day', '6 December 1915 – 12 December 1915', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kosturino'),
  ('Q2583507', 'Battle of the Cerna Bend', 'The Battle of the Cherna bend was a two-month-long battle between the Bulgarian and the Entente armies. The battle took place on the Macedonian front during the First World War Allied Monastir offensive in October and November 1916.', 1916, 11, 19, 1916, 11, NULL, 'day', '19 November 1916 – November 1916', 47, 'https://en.wikipedia.org/wiki/Battle_of_the_Crna_Bend_(1916)'),
  ('Q2889354', 'Monastir Offensive', 'The Monastir offensive was an Allied military operation against the forces of the Central Powers during World War I, intended to break the deadlock on the Macedonian front by forcing the capitulation of Bulgaria and relieving the pressure on Romania. The offensive took the shape of a large battle and lasted for three months and ended with the capture of the town of Monastir.', 1916, 9, 12, 1916, 12, 11, 'day', '12 September 1916 – 11 December 1916', 57, 'https://en.wikipedia.org/wiki/Monastir_offensive'),
  ('Q506916', 'Battle of Dobro Pole', 'The Battle of Dobro Pole (Serbian: Битка код Доброг Поља, romanized: Bitka kod Dobrog Polja; Greek: Μάχη του Ντόμπρο Πόλε, romanized: Máchi tou Dóbro Póle), also known as the Breakthrough at Dobro Pole (Bulgarian: Пробив при Добро Поле, romanized: Probiv pri Dobro Pole), was a World War I battle fought between 15 and 18 September 1918. The battle was fought in the initial stage of the Vardar offensive, in the Balkan Front.', 1918, 9, 15, NULL, NULL, NULL, 'day', '15 September 1918', 61, 'https://en.wikipedia.org/wiki/Battle_of_Dobro_Pole'),
  ('Q12908460', 'Massacre at Vataša', 'A massacre of 12 young people happened on 16 June 1943 near the village Vataša, Kavadarci, as part of the occupation of Vardar Banovina, part of the Kingdom of Yugoslavia by the Axis powers during World War II in Yugoslav Macedonia. The shooting happened near Moklište, where the neighborhood of "Čair" is, in the vicinity of the village of Vataša.', 1943, 6, 16, NULL, NULL, NULL, 'day', '16 June 1943', 34, 'https://en.wikipedia.org/wiki/Vata%C5%A1a_massacre'),
  ('Q12295674', 'Stracin-Kumanovo Operation', 'The Stracin–Kumanovo operation (Bulgarian: Страцинско-Кумановска операция) was an offensive operation conducted in 1944 by the Bulgarian Army against German forces in occupied Yugoslavia which culminated in the capture of Skopje in 1944. With the Bulgarian declaration of war on Germany on September 8, followed by the Bulgarian withdrawal from the area, the German 1st Mountain Division moved north, occupied Skopje, and secured the strategic Belgrade–Nis–Salonika railroad line.', 1944, 10, 8, 1944, 11, 14, 'day', '8 October 1944 – 14 November 1944', 37, 'https://en.wikipedia.org/wiki/Stracin%E2%80%93Kumanovo_operation'),
  ('Q3562567', 'Avioimpex Flight 110', 'Avioimpex Flight 110 was a scheduled international passenger flight operated by Avioimpex that crashed on 20 November 1993 while flying from Geneva to Skopje. Before the disaster, Flight 110 had deviated from Skopje International Airport to Ohrid Airport due to a blizzard in the Macedonian capital.', 1993, 11, 20, NULL, NULL, NULL, 'day', '20 November 1993', 52, 'https://en.wikipedia.org/wiki/Avioimpex_Flight_110'),
  ('Q7126582', 'Palair Macedonian Airlines Flight 301', 'Palair Macedonian Airlines Flight 301 was a scheduled international passenger flight from Skopje to Zurich, operated by Palair Macedonian, the then-flag carrier of Macedonia. On 5 March 1993, the aircraft operating the flight, a Fokker 100, crashed shortly after taking off from Skopje Airport in snowy conditions.', 1993, 3, 5, NULL, NULL, NULL, 'day', '5 March 1993', 48, 'https://en.wikipedia.org/wiki/Palair_Macedonian_Airlines_Flight_301'),
  ('Q28479', 'Kumanovo Agreement', 'The Military Technical Agreement, also known as the Kumanovo Agreement, signed between the International Security Force (KFOR) and the Governments of the Federal Republic of Yugoslavia and the Republic of Serbia, was an accord concluded on 9 June 1999 in Kumanovo, Macedonia. It resulted in the end of the Kosovo War, and established new basic relations between Yugoslavia and the Kosovo Force, which would replace units of the Yugoslav Army in Kosovo.', 1999, 6, 9, NULL, NULL, NULL, 'day', '9 June 1999', 63, 'https://en.wikipedia.org/wiki/Kumanovo_Agreement'),
  ('Q4872534', 'Battle of Tetovo', 'The Battle of Tetovo (Macedonian: Битка за Тетово, romanized: Bitka za Tetovo, Albanian: Beteja e Tetovës), that lasted from March to August 2001, was the largest engagement during the 2001 insurgency in Macedonia, in which Macedonian security forces battled the National Liberation Army (NLA) for control of the city.', 2001, 3, 16, 2001, 8, 13, 'day', '16 March 2001 – 13 August 2001', 45, 'https://en.wikipedia.org/wiki/Battle_of_Tetovo'),
  ('Q20563350', 'Aračinovo crisis', 'The Aračinovo crisis was a series of events triggered by the occupation of the village of Aračinovo, in the outskirts of the Macedonian capital Skopje, by the insurgent National Liberation Army (NLA) in June 2001 and the consequent attempts by the Macedonian army (ARM) to retake the settlement. The Macedonian attack resulted in a standoff with NATO, whose troops evacuated the besieged rebels after a ceasefire accord.', 2001, 6, 12, 2001, 6, 25, 'day', '12 June 2001 – 25 June 2001', 39, 'https://en.wikipedia.org/wiki/Ara%C4%8Dinovo_crisis'),
  ('Q20567764', 'Battle of Raduša', 'The battle of Raduša was part of the wider inter-ethnic conflict known as the insurgency in the Republic of Macedonia between the Albanian NLA and Macedonian security forces concentrated near the border with Kosovo. The brunt of the fighting happened near the village of Raduša and Bojane villages that guard the roads to the Rašče water supply which supplies water to the capital city of Skopje.', 2001, 6, 20, 2001, 8, 13, 'day', '20 June 2001 – 13 August 2001', 39, 'https://en.wikipedia.org/wiki/Battle_of_Radu%C5%A1a'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q3408413', 'Macedonian autonomy referendum', 'An autonomy referendum was held in Macedonia on 7 November 2004. Voters were asked whether they approved of overturning the municipal redistricting plans that gave greater autonomy to ethnic Albanians following the Ohrid Agreement that ended the 2001 conflict between ethnic Albanian militants and the predominantly ethnic Macedonian government forces.', 2004, 11, 7, NULL, NULL, NULL, 'day', '7 November 2004', 34, 'https://en.wikipedia.org/wiki/2004_Macedonian_autonomy_referendum'),
  ('Q26234218', '2016 Macedonian floods', 'In August 2016, several rainstorms hit the western and northwestern parts of the Republic of Macedonia. On 6 August, a storm with strong winds and flooding hit Skopje and the western parts of the country, leaving at least 21 people dead and dozens injured or missing.', 2016, 8, 6, NULL, NULL, NULL, 'day', '6 August 2016', 56, 'https://en.wikipedia.org/wiki/2016_Macedonian_floods'),
  ('Q55153903', 'Prespa agreement', 'The Prespa Agreement, also known as the Treaty of Prespa, the Prespes deal or the Prespa accord, is an agreement reached in 2018 between Greece and the then-Republic of Macedonia, under the auspices of the United Nations, resolving a long-standing naming dispute between the two countries. Apart from resolving the terminological differences, the agreement also covers areas of cooperation between the two countries in order to establish a strategic partnership.', 2018, 6, 17, NULL, NULL, NULL, 'day', '17 June 2018', 67, 'https://en.wikipedia.org/wiki/Prespa_Agreement'),
  ('Q55640952', 'Macedonian constitutional referendum, 2018', 'A referendum was held in the Republic of Macedonia on 30 September 2018, with voters asked whether they supported EU and NATO membership by accepting the Prespa Agreement between Macedonia and Greece, signed in June 2018, which aimed to settle the 27-year naming dispute, which had prevented Macedonia from joining both the European Union and NATO. The government, a coalition between the Social Democratic Union and the Democratic Union for Integration led by Prime Minister Zoran Zaev, strongly supported the agreement and encouraged a ''Yes'' vote in the referendum. The opposition, led by the…', 2018, 9, 30, NULL, NULL, NULL, 'day', '30 September 2018', 57, 'https://en.wikipedia.org/wiki/2018_Macedonian_referendum'),
  ('Q63078193', 'Regional Roaming Agreement', 'The Regional Roaming Agreement, formally the Agreement on the price reduction of the roaming services in public mobile communications networks in the Western Balkans region, regulates the imposition of roaming charges within the countries in the Western Balkans; Albania, Kosovo, Bosnia and Herzegovina, North Macedonia, Montenegro and Serbia. The agreement covers both the charges mobile network operators can impose on their subscribers for using telephone and data services outside of the network''s member state, and the wholesale rates networks can charge each other to allow their subscribers…', 2019, 4, 4, NULL, NULL, NULL, 'day', '4 April 2019', 41, 'https://en.wikipedia.org/wiki/Regional_Roaming_Agreement'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
